import pathlib,json,hashlib,collections,datetime,re
O=pathlib.Path(__file__).parent;L=O.parent;R=L/'root-mathdb-breadth-intake-r421'
def load(p):return json.loads(p.read_text())
def write(n,v):(O/n).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
def h(b):return hashlib.sha256(b).hexdigest()
# Validate direct registry originals against the registries' own manifests, without expanding history.
for name,targets in [('root-mathdb-accepted-exclusions-r304',{'accepted-exclusions.json','historical-dispositions.json'}),('root-mathdb-cayley-review-intake-r363',{'disposition.json','reserved-ids.json'})]:
 m=load(L/name/'manifest.json');entries=m if isinstance(m,list) else m['files']
 for x in entries:
  if x['path'] in targets:assert h((L/name/x['path']).read_bytes())==x['sha256']
ids=load(R/'reserved-ids.json')['ids'];baseline=load(R/'coverage-delta.json');assert len(baseline)==1933
assert not set(map(str,ids))&set(baseline)
assert not set(ids)&set(load(R/'reserved-ids.json')['other_active_reservations'])
assert not set(ids)&{372627,372628,368940,404067,364119}
rows={int(x.split('\t',1)[0]):x.rstrip('\n').split('\t')[1:] for x in (O/'assessments.tsv').read_text().splitlines()};assert set(rows)==set(ids)
rs=load(O/'selected-records.json');body={393113,393127,393142,393149,393159,393190,393203,393215,393224,393658,393659,393667,393668,393669,393677,393678}
# Only explicitly inspected sections are counted; downloaded pages are not counted as read.
out=[]
for r in rs:
 i=r['mathdb_id'];disp,scope,reason=rows[i]; p='primary/'+r['source_url'].rsplit('/',1)[1]+'.pdf'
 out.append({'mathdb_id':i,'title':r['title'],'literal_statement':r['statement'],'statement_sha256':h(r['statement'].encode()),'canonical_record_sha256':h(json.dumps(r,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()),'disposition':disp,'scope':scope,'reason':reason,'mechanism_assessment':reason,'evidence_levels':{'literal_full_cached_statement_read':True,'routing_only':False,'primary_problem_body_read':i in body,'primary_body_read_limit':'Only sections described in reason; no whole-report audit. Cited page offsets can be wrong.','successor_proof_body_read':i==393350,'successor_proof_limit':'For 393350, arXiv math/0505315v2 section 2, Theorem 2.8 through Corollary 2.14 inspected via web; even-size scope only. Other successor leads are not proof audits.','current_registry_cleared':False},'evidence':{'primary_url':r['source_url'],'primary_retained':p,'references_literal':r['references'],'excerpts':'primary-excerpts.json','successor_url':('https://arxiv.org/html/math/0505315' if i==393350 else None)},'primary_limits':'Download is not a technical audit. Definitions, source-internal examples and successor bodies not inspected are unresolved; no investment beyond this screen.','proof_limits':'No full-scope new proof or exact computational certificate produced. Public collection theorem reports distinguished from independently audited proofs.','registry_limits':'r304 accepted/historical and r363 exclusion are bound administrative evidence only. Current AIProofWatch request 403; route stopped, no retries. Current head and complete scope match missing: HOLD for any promotion.','bounded_check':{'executed':'Source/assignment/hash consistency only; no scientific finite sweep.','planned':'No investment assigned; further mathematical work requires a separate hypothesis-specific assignment and exact primary/successor scope audit.','certificate_size':'No candidate certificate.'},'formal_dependencies':'No formalization attempted; dependencies of unproposed mechanisms not resolved.','strongest_objection':reason,'prior_gaps':'Current registry incomplete; successor scope audits remain as stated. Empty solution arrays and open labels do not clear prior art.','qualified':False,'credit':0})
write('dispositions.json',out);write('proposals.json',[])
write('assignment-check.json',{'assigned':50,'statement_reviews':50,'baseline_reported_statement_reviews':1933,'disjoint_with_baseline':True,'disjoint_with_other_active_50':True,'explicit_exclusions_disjoint':True,'possible_reported_union_after_root_reconciliation':1983,'primary_sections_read':len(body),'successor_proof_sections_read':1,'qualified_briefs':0,'additional':9,'total':39,'next':40})
fail=load(O/'fetch-failures.json')+load(O/'successor-provenance.json')+ [load(O/'registry-provenance.json')]
fail=[x for x in fail if 'error' in x]
fail += [{'stage':'native successor inspection','error':'rg attempted beligiannis.txt and adjoint.txt before availability; both absent. No proof-body audit inferred.'},{'stage':'primary-page mapping','error':'393116 cited page 3 is TOC; 393168 cited page 20 is unrelated section. Source definitions not cleared.'},{'stage':'native output limits','error':'Some page/range outputs truncated, including figure-heavy report pages. Truncated/unseen text not counted as audited.'}]
write('failures.json',fail)
write('provenance.json',{'date_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'original_bindings':'bindings.json','originals_in_place':True,'corpus_copied':False,'recursive_binding_expansion':False,'upstream_verifiers_executed':False,'mathdb_requests':0,'public_search':'web searches used only as discovery leads; substantive evidence uses retained EMS source reports. No abstract-only clearance.','primary_fetch':'primary-provenance.json','successor_fetch':'successor-provenance.json','current_registry':'registry-provenance.json','external_proof_body_read':{'url':'https://arxiv.org/html/math/0505315','version':'v2, 17 Apr 2006; HTML displayed regenerated date August 24 2026, not used as proof chronology','sections':'2.5-2.14; proof of 2.8 inspected; cache not yet retained locally','scope':'Even-size factorization only; arbitrary-field odd-size question not cleared.'},'policies':{'resource_guard':'existing helper_guard.py; AS/group RSS 512MiB, CPU 210s, wall 230s','denied_routes':'MathDB inherited 429, AIM/Kourovka/EGRES inherited restrictions; AIProofWatch 403; no retries or alternate access routes','source_tls':'Certificate validation failure retained; no TLS bypass'},'counts_unchanged':{'additional':9,'total':39,'next':40}})
print('built',len(out),collections.Counter(x['disposition'] for x in out))
